#pragma once

#include "json.hpp"
#include "helper.hpp"

#include "BufferPath.hpp"
#include "ChunkCache.hpp"

namespace quicktype {
    void from_json(const json & j, ChunkCache & x);
    void to_json(json & j, const ChunkCache & x);

    void from_json(const json & j, BufferPath & x);
    void to_json(json & j, const BufferPath & x);

    inline void from_json(const json & j, ChunkCache& x) {
        if (!j.is_object()) throw std::runtime_error("Expected object");
        x.set_chunks(j.at("chunks").get<std::vector<std::string>>());
        if (j.find("size") != j.end() && !j.at("size").is_number_integer()) throw std::runtime_error("Expected integer");
        x.set_size(j.at("size").get<int64_t>());
    }

    inline void to_json(json & j, const ChunkCache & x) {
        j = json::object();
        j["chunks"] = x.get_chunks();
        j["size"] = x.get_size();
    }

    inline void from_json(const json & j, BufferPath& x) {
        if (!j.is_object()) throw std::runtime_error("Expected object");
        x.set_path(j.at("path").get<std::string>());
        if (j.find("maxSize") != j.end() && !j.at("maxSize").is_number_integer()) throw std::runtime_error("Expected integer");
        x.set_max_size(j.at("maxSize").get<int64_t>());
    }

    inline void to_json(json & j, const BufferPath & x) {
        j = json::object();
        j["path"] = x.get_path();
        j["maxSize"] = x.get_max_size();
    }
}

