#pragma once

#include "json.hpp"
#include "helper.hpp"

namespace quicktype {
    using nlohmann::json;

    class ChunkCache {
        public:
        ChunkCache() = default;
        virtual ~ChunkCache() = default;

        private:
        std::vector<std::string> chunks;
        int64_t size;

        public:
        const std::vector<std::string> & get_chunks() const { return chunks; }
        std::vector<std::string> & get_mutable_chunks() { return chunks; }
        void set_chunks(const std::vector<std::string> & value) { this->chunks = value; }

        const int64_t & get_size() const { return size; }
        int64_t & get_mutable_size() { return size; }
        void set_size(const int64_t & value) { this->size = value; }
    };
}

